def window_maxima(nums: list[int], k: int) -> list[int]:
    """Return the maximum of every contiguous window of length `k` in `nums`,
    from left to right.

    There are len(nums) - k + 1 windows. Raise ValueError if k < 1 or
    k > len(nums) (so an empty list always raises).

    >>> window_maxima([1, 3, -1, -3, 5, 3, 6, 7], 3)
    [3, 3, 5, 5, 6, 7]
